document.addEventListener('DOMContentLoaded',()=>{initMobileMenu();initSPARouter();initThemeToggle()});function initMobileMenu(){const hamburgerBtn=document.getElementById('hamburger-btn');const mainNav=document.getElementById('main-nav');if(hamburgerBtn&&mainNav){hamburgerBtn.addEventListener('click',()=>{mainNav.classList.toggle('active')})}}
const mainContent=document.getElementById('main-content');const pageCache=new Map();async function loadPageContent(path,hash){if(!mainContent)return;document.getElementById('main-nav').classList.remove('active');let pagePath=(path==='/'||path.endsWith('index.html'))?'/home.html':path;let content='';if(pageCache.has(pagePath)){content=pageCache.get(pagePath)}else{try{const response=await fetch(pagePath);if(!response.ok)throw new Error('Página não encontrada.');content=await response.text();pageCache.set(pagePath,content)}catch(error){console.error('Erro ao carregar página:',error);content=`<div class="container"><p>Erro ao carregar o conteúdo. Tente novamente.</p></div>`}}
mainContent.innerHTML=content;if(hash){setTimeout(()=>{const element=document.querySelector(hash);if(element){element.scrollIntoView({behavior:'smooth'})}},0)}
if(pagePath==='/cadastro.html'){initFormValidation()}}
function initSPARouter(){document.body.addEventListener('click',event=>{const target=event.target.closest('a');if(!target||!target.classList.contains('spa-link')){return}
event.preventDefault();const href=target.getAttribute('href');const url=new URL(href,window.location.origin);const path=url.pathname;const hash=url.hash;if(window.location.href!==url.href){history.pushState({path},'',href)}
loadPageContent(path,hash)});window.addEventListener('popstate',(event)=>{const path=window.location.pathname;const hash=window.location.hash;loadPageContent(path,hash)});const initialPath=window.location.pathname;const initialHash=window.location.hash;loadPageContent(initialPath,initialHash)}
function initFormValidation(){const form=document.getElementById('form-cadastro');if(!form)return;form.addEventListener('submit',event=>{event.preventDefault();let isFormValid=!0;form.querySelectorAll('.input-error').forEach(input=>{input.classList.remove('input-error')});const inputs=form.querySelectorAll('input[required]');inputs.forEach(input=>{let isValid=input.checkValidity();if(input.id==='nome'&&input.value.trim().length<3){isValid=!1}
if(!isValid){isFormValid=!1;input.classList.add('input-error')}});if(isFormValid){console.log('Formulário válido. Enviando...');const successMsg=document.getElementById('form-success-message');if(successMsg)successMsg.style.display='block';form.reset();setTimeout(()=>{if(successMsg)successMsg.style.display='none'},4000)}else{console.log('Formulário inválido.')}})}
function initThemeToggle(){const toggleBtn=document.getElementById('theme-toggle-btn');if(!toggleBtn)return;function applyTheme(theme){if(theme==='dark'){document.documentElement.setAttribute('data-theme','dark');toggleBtn.innerHTML='&#9728;'}else{document.documentElement.removeAttribute('data-theme');toggleBtn.innerHTML='&#127769;'}}
let savedTheme=localStorage.getItem('theme');if(!savedTheme){savedTheme=window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}
applyTheme(savedTheme);toggleBtn.addEventListener('click',()=>{let currentTheme=document.documentElement.getAttribute('data-theme');if(currentTheme==='dark'){localStorage.setItem('theme','light');applyTheme('light')}else{localStorage.setItem('theme','dark');applyTheme('dark')}})}